        self.assertNotIn("CHECKED_BY", preflight)
        self.assertNotIn("CHECKED_DATE", preflight)
        self.assertNotIn("APPROVED_DATE", preflight)
        self.assertIn("variable: 'SHEET_LEGAL_NOTICE'", preflight)
